import type { Metadata } from 'next';

/**
 * Per-page metadata. Keep descriptions under about 160 characters.
 * `og` is the image name under public/og/ without extension (generated by scripts/og/og.mjs).
 */
export const SITE_URL = process.env.SITE_URL || 'https://www.ixian.io';

export function pageMeta({ title, description, path = '/', og = 'home', ogAlt }: { title: string; description: string; path?: string; og?: string; ogAlt?: string }): Metadata {
  const OG_IMAGE = { url: `${SITE_URL}/og/${og}.jpg`, width: 1200, height: 630, alt: ogAlt ?? title };
  return {
    title,
    description,
    metadataBase: new URL(SITE_URL),
    alternates: { canonical: path },
    openGraph: {
      type: 'website',
      locale: 'en_US',
      siteName: 'Ixian',
      url: `${SITE_URL}${path}`,
      title,
      description,
      images: [OG_IMAGE],
    },
    twitter: {
      card: 'summary_large_image',
      site: '@ixian_IO',
      title,
      description,
      images: [OG_IMAGE],
    },
  };
}
